const handlebars = context.handlebars;

handlebars.registerHelper('equity_calendar', function(rows) {
  if (!rows || !rows.length) {
    return new handlebars.SafeString('<p style="color:#888;padding:16px">Sem dados no intervalo selecionado.</p>');
  }

  var dayMap = {};
  var minDay = null, maxDay = null;
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i];
    var ds = r.day ? String(r.day).slice(0, 10) : null;
    if (!ds) continue;
    dayMap[ds] = { pct: parseFloat(r.pnl_pct || 0), usdt: parseFloat(r.pnl_usdt || 0) };
    if (!minDay || ds < minDay) minDay = ds;
    if (!maxDay || ds > maxDay) maxDay = ds;
  }

  if (!minDay) {
    return new handlebars.SafeString('<p style="color:#888;padding:16px">Sem dados no intervalo selecionado.</p>');
  }

  function getColor(pct) {
    if (pct === null || pct === undefined) return 'rgba(255,255,255,0.04)';
    if (pct >  1.0) return '#1a7a1a';
    if (pct >  0.3) return '#2a8f2a';
    if (pct >  0.0) return '#4aab4a';
    if (pct === 0)  return 'rgba(255,255,255,0.06)';
    if (pct > -0.3) return '#ab4a4a';
    if (pct > -1.0) return '#8f2a2a';
    return '#7a1a1a';
  }

  var today = new Date();
  var mNames = ['Janeiro','Fevereiro','Março','Abril','Maio','Junho',
                'Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];

  function pad(n) { return String(n).padStart(2, '0'); }

  function renderMonth(yr, mo) {
    var first    = new Date(yr, mo, 1);
    var last     = new Date(yr, mo + 1, 0);
    var startDow = first.getDay();

    var g = '<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:3px;">';
    ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].forEach(function(l) {
      g += '<div style="text-align:center;color:#666;font-size:11px;font-weight:600;padding:3px 0">' + l + '</div>';
    });
    for (var e = 0; e < startDow; e++) g += '<div></div>';
    for (var day = 1; day <= last.getDate(); day++) {
      var ds      = yr + '-' + pad(mo + 1) + '-' + pad(day);
      var info    = dayMap[ds];
      var isToday = (today.getFullYear() === yr && today.getMonth() === mo && today.getDate() === day);
      var bg      = info ? getColor(info.pct) : 'rgba(255,255,255,0.03)';
      var border  = isToday ? '2px solid #ffd700' : '1px solid rgba(255,255,255,0.06)';
      var ttip    = info ? ds + ': ' + (info.pct >= 0 ? '+' : '') + info.pct.toFixed(3) + '% ($' + (info.usdt >= 0 ? '+' : '') + info.usdt.toFixed(2) + ')' : ds;
      var pctStr  = info ? (info.pct >= 0 ? '+' : '') + info.pct.toFixed(2) + '%' : '';
      var usdtStr = info ? (info.usdt >= 0 ? '+' : '') + info.usdt.toFixed(2) : '';
      g += '<div title="' + ttip + '" style="background:' + bg + ';border:' + border + ';border-radius:5px;min-height:52px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;cursor:default">'
        + '<span style="font-size:14px;color:rgba(255,255,255,' + (isToday ? '1' : '0.85') + ');font-weight:' + (isToday ? 700 : 400) + '">' + day + '</span>'
        + (info ? '<span style="font-size:11px;color:rgba(255,255,255,0.9);font-weight:600">' + pctStr + '</span>' : '')
        + (info ? '<span style="font-size:9px;color:rgba(255,255,255,0.6)">' + usdtStr + '</span>' : '')
        + '</div>';
    }
    g += '</div>';
    return '<div style="margin-bottom:20px">'
      + '<div style="font-size:17px;font-weight:700;color:#e0e0e0;text-align:center;margin-bottom:6px">' + mNames[mo] + ' ' + yr + '</div>'
      + g
      + '</div>';
  }

  var sy = parseInt(minDay.slice(0,4)), sm = parseInt(minDay.slice(5,7)) - 1;
  var ey = parseInt(maxDay.slice(0,4)), em = parseInt(maxDay.slice(5,7)) - 1;
  var months = '';
  var cy = sy, cm = sm;
  while (cy < ey || (cy === ey && cm <= em)) {
    months += renderMonth(cy, cm);
    cm++;
    if (cm > 11) { cm = 0; cy++; }
  }

  var legend = [
    ['#1a7a1a', '>+1%'], ['#2a8f2a', '+0.3–+1%'], ['#4aab4a', '0–+0.3%'],
    ['rgba(255,255,255,0.06)', 'sem dado'],
    ['#ab4a4a', '0–-0.3%'], ['#8f2a2a', '-0.3–-1%'], ['#7a1a1a', '<-1%']
  ].map(function(l) {
    return '<span style="background:' + l[0] + ';border-radius:4px;padding:3px 10px;color:rgba(255,255,255,0.9);font-size:12px">' + l[1] + '</span>';
  }).join('');

  return new handlebars.SafeString(
    '<div style="padding:12px 16px;font-family:Inter,sans-serif;width:100%;height:100%;box-sizing:border-box;display:flex;flex-direction:column;gap:8px;overflow-y:auto">'
    + '<div>'
    +   '<div style="font-size:15px;font-weight:700;color:#FF9830">📅 PnL Diário — Equity vs Exchange</div>'
    +   '<div style="color:#8e8ea0;font-size:11px">Variação patrimônio total (USDT livre + BTC a mercado)</div>'
    + '</div>'
    + months
    + '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding-top:4px">'
    +   '<span style="color:#8e8ea0;font-size:11px">Legenda:</span>' + legend
    + '</div>'
    + '</div>'
  );
});

const handlebars = context.handlebars;

handlebars.registerHelper('trading_month_report', function(rows) {
  if (!rows || !rows.length) {
    return new handlebars.SafeString('<p style="color:#888;padding:12px">Sem dados para o mês corrente.</p>');
  }
  function esc(v) {
    if (v === null || v === undefined) return '';
    return String(v).replace(/[&<>"']/g, function(c) {
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }
  function num(v, digits, signed) {
    var n = parseFloat(v || 0);
    var s = n.toFixed(digits);
    return signed && n >= 0 ? '+' + s : s;
  }
  function cls(v) {
    var n = parseFloat(v || 0);
    if (n > 0) return 'pos';
    if (n < 0) return 'neg';
    return 'zero';
  }
  var meta = rows.find(function(r) { return r.kind === 'meta'; }) || {};
  var accounts = rows.filter(function(r) { return r.kind === 'account'; });
  var daily = rows.filter(function(r) { return r.kind === 'daily'; });
  var updated = meta.last_seen ? String(meta.last_seen).slice(0, 16).replace('T', ' ') : '--';
  var html = '<div class="tmr">'
    + '<div class="tmr-head"><div><div class="tmr-title">Relatório mensal do agent trading</div>'
    + '<div class="tmr-sub">Atualiza pelo refresh do dashboard; novos fechamentos de slot entram quando o SELL e os snapshots chegam ao Postgres.</div></div>'
    + '<div class="tmr-chip">Atualizado: ' + esc(updated) + '</div></div>'
    + '<div class="tmr-meta"><span>Realizado no mês: <b class="' + cls(meta.value_usdt) + '">' + num(meta.value_usdt, 4, true) + ' USDT</b></span><span>' + esc(meta.balances || '') + '</span></div>';
  html += '<div class="tmr-section">Saldo atual</div><table><thead><tr><th>Conta</th><th class="num">Valor USDT</th><th>Saldos</th></tr></thead><tbody>';
  accounts.forEach(function(r) {
    html += '<tr><td>' + esc(r.label) + '</td><td class="num">' + num(r.value_usdt, 2, false) + '</td><td>' + esc(r.balances) + '</td></tr>';
  });
  html += '</tbody></table>';
  html += '<div class="tmr-section">Rendimento dia a dia do mês</div><table><thead><tr><th>Dia</th><th class="num">Saldo inicial</th><th class="num">Saldo final</th><th class="num">Var. MTM</th><th class="num">Var. %</th><th class="num">PnL realizado</th><th class="num">Compras</th><th class="num">Vendas</th></tr></thead><tbody>';
  daily.forEach(function(r) {
    html += '<tr title="' + esc(r.note || '') + '"><td>' + esc(r.label) + (r.note ? ' <span class="warn">*</span>' : '') + '</td>'
      + '<td class="num">' + num(r.start_usdt, 2, false) + '</td>'
      + '<td class="num">' + num(r.end_usdt, 2, false) + '</td>'
      + '<td class="num ' + cls(r.mtm_change_usdt) + '">' + num(r.mtm_change_usdt, 2, true) + '</td>'
      + '<td class="num ' + cls(r.mtm_pct) + '">' + num(r.mtm_pct, 3, true) + '%</td>'
      + '<td class="num ' + cls(r.realized_pnl_usdt) + '">' + num(r.realized_pnl_usdt, 4, true) + '</td>'
      + '<td class="num">' + esc(r.buys || 0) + '</td><td class="num">' + esc(r.sells || 0) + '</td></tr>';
  });
  html += '</tbody></table>';
  var notes = daily.filter(function(r) { return r.note; }).map(function(r) { return '<div><b>' + esc(r.label) + ':</b> ' + esc(r.note) + '</div>'; }).join('');
  if (notes) html += '<div class="tmr-note">' + notes + '</div>';
  html += '</div>';
  return new handlebars.SafeString(html);
});

options.styles:
.tmr { font-family: Inter, sans-serif; padding: 10px 12px 16px; color: #d8d9da; height: 100%; overflow: auto; box-sizing: border-box; }
.tmr-head { display: flex; justify-content: space-between; gap: 12px; align-items: flex-start; margin-bottom: 8px; }
.tmr-title { font-size: 16px; font-weight: 700; color: #f2f3f5; }
.tmr-sub { color: #9da2a8; font-size: 11px; margin-top: 2px; }
.tmr-chip { border: 1px solid rgba(255,255,255,0.14); border-radius: 4px; padding: 4px 8px; font-size: 11px; white-space: nowrap; color: #c8ccd0; }
.tmr-meta { display: flex; flex-wrap: wrap; gap: 8px 16px; color: #bec3c7; font-size: 12px; margin: 8px 0 12px; }
.tmr-section { font-size: 13px; font-weight: 700; color: #f2f3f5; margin: 12px 0 6px; }
.tmr table { width: 100%; border-collapse: collapse; table-layout: auto; font-size: 12px; }
.tmr th { color: #bfc3c8; font-weight: 700; text-align: left; border-bottom: 1px solid rgba(255,255,255,0.12); padding: 7px 8px; }
.tmr td { border-bottom: 1px solid rgba(255,255,255,0.07); padding: 7px 8px; vertical-align: top; }
.tmr .num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.tmr .pos { color: #73bf69; }
.tmr .neg { color: #f2495c; }
.tmr .zero { color: #d8d9da; }
.tmr .warn { color: #ffb357; font-weight: 700; }
.tmr-note { color: #b8bdc3; font-size: 11px; margin-top: 8px; line-height: 1.35; }
